import{_ as a,o as e,c as d,a6 as s}from"./chunks/framework.De615z8S.js";const b=JSON.parse('{"title":"便携榨汁杯详情页：逐屏制作再拼接","description":"","frontmatter":{"id":"detail-page","title":"便携榨汁杯详情页：逐屏制作再拼接","chapter":"03","status":"已公开","evidence_status":"按原稿重写并核对官方操作资料；未执行生图、软件操作或平台上传","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":[],"order":22,"content_kind":"操作教程","tool_ids":["photopea","photoshop"]},"headers":[],"relativePath":"ecommerce/detail-page.md","filePath":"ecommerce/detail-page.md"}'),n={name:"ecommerce/detail-page.md"};function p(r,t,i,o,l,h){return e(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="便携榨汁杯详情页-逐屏制作再拼接" tabindex="-1">便携榨汁杯详情页，逐屏制作再拼接 <a class="header-anchor" href="#便携榨汁杯详情页-逐屏制作再拼接" aria-label="Permalink to &quot;便携榨汁杯详情页，逐屏制作再拼接&quot;">​</a></h1><p>沿用原稿的便携榨汁杯案例，把六张商品图扩展成详情页。做完应有逐屏文案、10个可单独导出的模块、整页预览和可编辑排版源文件。原稿的场景提示词保留，产品规格、无线充电、安全锁和食品接触声明改为有真实依据才展示。</p><p>先准备<a href="./product-brief">商品简报</a>与<a href="./image-set">套图母版</a>。产品照片、局部照片、使用说明、颜色实拍、规格与售后资料分别存放。详情页先确定各屏回答的问题，再作图，这样能发现哪些屏缺证据。</p><h2 id="_1-给十屏写好文案和素材任务" tabindex="-1">1. 给十屏写好文案和素材任务 <a class="header-anchor" href="#_1-给十屏写好文案和素材任务" aria-label="Permalink to &quot;1. 给十屏写好文案和素材任务&quot;">​</a></h2><table tabindex="0"><thead><tr><th>屏</th><th>读者问题</th><th>图片怎么来</th><th>文案怎么写</th></tr></thead><tbody><tr><td>01主视觉</td><td>这是什么、适合什么日常</td><td>厨房背景＋真实商品</td><td>产品名与一句场景价值</td></tr><tr><td>02卖点总览</td><td>最值得看哪几件事</td><td>真实商品＋三块留白</td><td>三条已核实卖点</td></tr><tr><td>03使用场景</td><td>家里、办公室怎么放</td><td>一个具体场景一张图</td><td>场景名，不虚构性能</td></tr><tr><td>04结构细节</td><td>杯盖、按钮、杯体是什么样</td><td>局部实拍</td><td>实际部件名称</td></tr><tr><td>05尺寸</td><td>放不放得下、带不带得走</td><td>正面/侧面实拍＋标注</td><td>真实外尺寸、重量</td></tr><tr><td>06使用</td><td>怎么启动和结束</td><td>真实动作照片</td><td>说明书步骤</td></tr><tr><td>07清洗/注意</td><td>哪些能洗、哪些不能洗</td><td>拆卸实拍或说明图</td><td>必要条件和限制</td></tr><tr><td>08颜色</td><td>两个颜色到底差在哪</td><td>同光线同角度SKU实拍</td><td>对应变体名称</td></tr><tr><td>09规格/发货</td><td>参数和配件是多少</td><td>表格＋真实平铺</td><td>有来源的数值与数量</td></tr><tr><td>10售后</td><td>怎么联系、能得到什么服务</td><td>准确文字为主</td><td>已确认的售后条款</td></tr></tbody></table><p>先在文档里填全这张表。没有安全结构证明就把原稿的“安全锁设计”屏改为已知使用注意；没有售后政策就不编承诺。多屏缺素材时先发布有依据的模块，别靠背景海报凑长页。</p><h2 id="_2-首屏主视觉-留出标题区" tabindex="-1">2. 首屏主视觉，留出标题区 <a class="header-anchor" href="#_2-首屏主视觉-留出标题区" aria-label="Permalink to &quot;2. 首屏主视觉，留出标题区&quot;">​</a></h2><p>在图像画布上传真实商品图，选择竖向画幅，输入下面的任务词。首屏的职责是让读者认出商品，果昔和水果只做场景道具。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>上传照片中的便携榨汁杯是唯一商品依据，保留外观、颜色、按钮、杯盖、底座和标识。制作详情页首屏背景，产品放在明亮厨房浅木台面上，窗光从左前方进入，奶油白与少量浅绿色，真实生活方式摄影。</span></span>
<span class="line"><span>产品位于画面中下部，顶部约四分之一简洁留白，供后期排产品名和一句标题。远处少量草莓与香蕉，不遮商品，不表示随商品发货。不生成任何文字、数字、图标、认证或水印，不改变商品结构。</span></span></code></pre></div><p>商品发生变化就只生成背景，在PS/Photopea放回真实主体。标题和副标题用文字层做。把首屏缩成手机宽度看，第一眼能辨认杯子，第二眼能读到产品名，就够进入下一屏。</p><h2 id="_3-第二屏卖点总览-别把参数塞在背景里" tabindex="-1">3. 第二屏卖点总览，别把参数塞在背景里 <a class="header-anchor" href="#_3-第二屏卖点总览-别把参数塞在背景里" aria-label="Permalink to &quot;3. 第二屏卖点总览，别把参数塞在背景里&quot;">​</a></h2><p>先从事实表挑3条最相关的卖点，每条用“事实＋读者能理解的用途”写短句。便携不是一个自动成立的功能，需要尺寸与重量支持；易清洗要有拆洗方式支持。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>生成便携榨汁杯详情页卖点总览的无字底图。真实商品外观以上传照片为准，商品放在画面中间偏下，背景奶油白，少量浅绿色，柔和影棚光。</span></span>
<span class="line"><span>上方留标题空间，商品左右各留简洁空白，便于后期放三条已核实卖点。不要文字、数字、箭头、图标、夸张能量光效或认证标记，不添加不存在的零件和配件。</span></span></code></pre></div><p>得到底图后，把三条卖点排成独立文本组。图标若使用，必须对应事实，不能用闪电图标暗示未核实的充电性能。手机上若三块文字拥挤，拆为两屏，比缩小字号更合适。</p><h2 id="_4-第三屏做办公室场景" tabindex="-1">4. 第三屏做办公室场景 <a class="header-anchor" href="#_4-第三屏做办公室场景" aria-label="Permalink to &quot;4. 第三屏做办公室场景&quot;">​</a></h2><p>沿用同一产品和光线，避免厨房图是奶油白，办公室图变成纯白或绿色。选择实际适用的使用环境，不能通过画面暗示产品能够在不允许的场合工作。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>保持上传实拍中的便携榨汁杯外观、颜色、标识和比例。制作办公室桌面生活方式副图，浅木桌面，笔记本电脑在远处虚化，少量水果放在边缘，产品为主角。窗光从左侧照入，干净自然，不使用强烈霓虹或镜面反射。</span></span>
<span class="line"><span>留一处空白用于后期写场景标题，不生成文字、数字或图标，不增加产品功能，不添加不随商品出售的配件展示组合。</span></span></code></pre></div><p>图中电脑应小于商品的视觉重点，道具不能遮杯盖。若商品悬空，修接触阴影；若视角不合，换背景或对应角度实拍，不能扭曲商品形状。</p><h2 id="_5-第四到九屏-真实资料接管" tabindex="-1">5. 第四到九屏，真实资料接管 <a class="header-anchor" href="#_5-第四到九屏-真实资料接管" aria-label="Permalink to &quot;5. 第四到九屏，真实资料接管&quot;">​</a></h2><p>结构屏用局部实拍裁切。尺寸屏用测量值和矢量线。使用与清洗屏按说明书拍动作。颜色屏用同光线同角度实拍并排。规格屏在文字层或表格里输入，不让整图模型猜数字。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>依据我提供的商品事实表、说明书、颜色照片和配件清单，输出便携榨汁杯详情页04至09屏的排版文案。</span></span>
<span class="line"><span>每屏写标题、最多三条短说明、需要使用的照片文件名、图层顺序。尺寸数值保留原单位和来源；颜色名称与SKU对应；使用和清洗必须符合说明书。缺失资料标待补，禁止推测功率、容量、刀头数量、充电方式、安全功能和认证。</span></span>
<span class="line"><span>输出一张逐屏表，另列尚缺的照片和参数。不生成商品图片，不以AI纹理替代实拍细节。</span></span></code></pre></div><h2 id="_6-在图层软件完成排版" tabindex="-1">6. 在图层软件完成排版 <a class="header-anchor" href="#_6-在图层软件完成排版" aria-label="Permalink to &quot;6. 在图层软件完成排版&quot;">​</a></h2><p>本练习可用750像素宽的工作模块，模块高度按内容确定；这是设计起点，正式上传按平台当前要求。每个模块分别建商品、背景、文案、标注组，标题字体和边距一致。Photopea使用文字工具拖文本框，避免把一段话写成超长单行；准确文字保留文字层。<a href="https://www.photopea.com/learn/text" target="_blank" rel="noreferrer">文字操作</a>。</p><p>首屏可以更高，规格屏可短一些。不要机械地让十屏等高。图片上留白太多时裁掉无用区域，但不裁掉商品、数字和必要安全说明。完成一个模块后先导出，确认手机可读再复制排版样式到其他模块。</p><h2 id="_7-拼接与返工" tabindex="-1">7. 拼接与返工 <a class="header-anchor" href="#_7-拼接与返工" aria-label="Permalink to &quot;7. 拼接与返工&quot;">​</a></h2><p>把模块按01到10排列成整页预览，同时保留分屏文件。连续看整页，出现三屏都在讲“便携”就合并或替换为真实信息；某屏全是水果而商品很小，就重新构图。导出后查看屏与屏的接缝、字体大小、颜色、数值和安全说明。</p><table tabindex="0"><thead><tr><th>具体问题</th><th>修法</th></tr></thead><tbody><tr><td>三屏文案重复</td><td>回第1步分配不同买家问题</td></tr><tr><td>产品在各屏颜色不同</td><td>换回同一真实商品层，统一背景色</td></tr><tr><td>手机参数字太小</td><td>拆规格组，删次要说明，放大数值</td></tr><tr><td>拼接有大段白缝</td><td>检查各模块底部留白，不靠负行距压缩</td></tr><tr><td>安全说明被裁掉</td><td>扩充模块高度，重新导出</td></tr></tbody></table><p>交付时同时给分屏图、整页图、准确文案和PSD状态。平台上传与手机实际页面还要另检查。本项目本页未生图或实操排版。Amazon A+需要重新选择后台模块，接着读<a href="./amazon-a-plus">A+模块制作</a>，不能把这张长图直接套进去。</p>`,28)])])}const u=a(n,[["render",p]]);export{b as __pageData,u as default};
